/**
 * Sort's fixed level catalog (#2761): the 120 levels every player gets, in 6
 * chapters of 20, shipped inside the app. Nothing is fetched: the levels work
 * offline, and level N is the same puzzle for everyone, so best moves compare
 * on the leaderboard.
 *
 * `levels.catalog.json` is generated by `backend/scripts/sort_build_catalog.py`
 * (never edit it by hand); the backend tests regenerate it and replay every
 * level's solution. Format: `legend` lists the colour names (letter `A` is
 * `legend[0]`); each level is `[bottles, par]`, its bottles bottom first, one
 * letter per unit, joined by `,` (an empty bottle is an empty string).
 *
 * Pure data. No React, no side effects.
 */
import catalogJson from "./levels.catalog.json";
import type { Color } from "./types";

export interface LevelData {
  readonly id: number;
  readonly bottles: readonly (readonly Color[])[];
}

export interface CatalogLevel extends LevelData {
  /**
   * The solver's solution length plus 15%, rounded up: the move count a good
   * solve meets. Read by the per-level stars (#3687).
   */
  readonly par: number;
}

interface CatalogFile {
  readonly version: number;
  readonly legend: readonly string[];
  readonly levels: readonly (readonly [string, number])[];
}

/** Decodes one catalog level's bottles. Throws on a letter outside the legend. */
export function decodeBottles(encoded: string, legend: readonly string[]): Color[][] {
  return encoded.split(",").map((bottle) =>
    Array.from(bottle, (letter) => {
      const color = legend[letter.charCodeAt(0) - 65];
      if (color === undefined) throw new Error(`sort catalog: unknown colour ${letter}`);
      return color as Color;
    })
  );
}

/** Decodes a catalog file into levels numbered from 1. Pure. */
export function decodeCatalog(file: CatalogFile): CatalogLevel[] {
  return file.levels.map(([bottles, par], i) => ({
    id: i + 1,
    bottles: decodeBottles(bottles, file.legend),
    par,
  }));
}

const catalog = catalogJson as unknown as CatalogFile;

/**
 * The catalog's version. Sent with every scored solve (`catalog_version`) so
 * the leaderboard only ranks this catalog's solves, and stored with the
 * player's progress (`@sort/catalog_version`) so a later catalog can migrate
 * it (`catalogMigration.ts`). Raised whenever the levels change.
 */
export const SORT_CATALOG_VERSION: number = catalog.version;

/** Levels per chapter: the level grid groups the catalog under chapter headers (#3687). */
export const CHAPTER_SIZE = 20;

/** Every level, level 1 first. */
export const SORT_LEVELS: readonly CatalogLevel[] = decodeCatalog(catalog);
